;WITH N AS
(
    SELECT TOP (30) ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) AS n
    FROM sys.all_objects
)
INSERT dbo.Users (Username, PasswordHash, RoleName)
SELECT CONCAT('customer', RIGHT(CONCAT('00', n), 2)), 'demo_hash_customer', 'customer'
FROM N;
GO

